package com.frostsecurity.extreme.dashboard;
import com.frostsecurity.extreme.core.*; import com.frostsecurity.extreme.network.NetworkMonitor; import com.frostsecurity.extreme.recon.ServerProfile; import com.frostsecurity.extreme.reports.*; import net.minecraft.client.gui.DrawContext; import net.minecraft.client.gui.screen.Screen; import net.minecraft.client.gui.widget.ButtonWidget; import net.minecraft.text.Text; import java.nio.file.*;
public final class DashboardScreen extends Screen { public DashboardScreen(){super(Text.literal("FROST SECURITY SCANNER EXTREME"));} @Override protected void init(){int y=height/2+35; addDrawableChild(ButtonWidget.builder(Text.literal("Gerar relatório"),b->{try{var r=ReportGenerator.build("cliente atual");ReportGenerator.writeHtml(r,Paths.get(System.getProperty("user.dir"),"frostscan-data","report-"+r.id()+".html"));}catch(Exception ignored){}}).dimensions(width/2-110,y,105,20).build());addDrawableChild(ButtonWidget.builder(Text.literal("Limpar alertas"),b->SecurityEngine.clear()).dimensions(width/2+5,y,105,20).build());} @Override public void render(DrawContext c,int mouseX,int mouseY,float delta){renderBackground(c,mouseX,mouseY,delta);c.drawTextWithShadow(textRenderer,"FROST SECURITY SCANNER EXTREME",20,20,0x59D8FF);ServerProfile s=ServerProfile.current();var n=NetworkMonitor.snapshot();c.drawTextWithShadow(textRenderer,"Servidor: "+s.address(),20,48,0xDCEBFF);c.drawTextWithShadow(textRenderer,"Latência: "+n.latencyMs()+" ms | Sessão: "+n.sessionSeconds()+" s",20,66,0xDCEBFF);c.drawTextWithShadow(textRenderer,"Alertas: "+SecurityEngine.findings().size(),20,84,0xDCEBFF);c.drawTextWithShadow(textRenderer,"Estado: "+(NetworkMonitor.connected()?"CONECTADO":"DESCONECTADO"),20,102,0x8FE9FF);int y=140;c.drawTextWithShadow(textRenderer,"Últimos achados",20,y,0xFFFFFF);for(var f:SecurityEngine.findings().reversed().stream().limit(8).toList()){y+=18;c.drawTextWithShadow(textRenderer,"["+f.severity()+"] "+f.title(),28,y,0xDCEBFF);}super.render(c,mouseX,mouseY,delta);} }
